// Build the discussion seeds from the incident payload (PagerDuty v3 shape).
const inc = $('Incident Webhook').first().json.body.event.data;
const facts = [
  `Incident: ${inc.title} (${inc.priority?.summary ?? 'unprioritised'})`,
  `Opened ${inc.created_at} — resolved ${$('Incident Webhook').first().json.body.event.occurred_at}`,
  `Service affected: ${inc.service?.summary ?? 'unknown'}`,
  `What surprised us during this incident?`,
  `Where did our alerting / runbooks fall short?`,
];
return facts.map(title => ({ json: { title } }));
